// SDK is available as a global 'sdk' variable

async function run() {
    // List entries from a CMS model
    const result = await sdk.cms.listEntries({
        modelId: "article",
        fields: ["id", "createdOn", "values.title"]
    });

    // Handle the result
    if (result.isOk()) {
        console.log(result.value);
    } else {
        console.error(result.error);
    }
}

run();
